# ──────────────────────────────────────────────
# 열거형 정의
# ──────────────────────────────────────────────

class 공정상태(Enum):
    """생산 공정의 현재 상태를 나타냅니다."""
    대기중 = "WAITING"
    진행중 = "IN_PROGRESS"
    완료 = "COMPLETED"
    불량 = "DEFECT"
    보류 = "ON_HOLD"


class 불량유형(Enum):
    """품질 검사에서 발견된 불량 유형입니다."""
    치수불량 = "DIMENSION_DEFECT"
    외관불량 = "APPEARANCE_DEFECT"
    기능불량 = "FUNCTIONAL_DEFECT"
    재료불량 = "MATERIAL_DEFECT"


# ──────────────────────────────────────────────
# 데이터 클래스
# ──────────────────────────────────────────────

@dataclass
class 작업지시:
    """
    생산 작업 지시 정보를 담는 데이터 클래스입니다.

    Attributes:
        지시번호: 고유 작업 지시 번호 (예: WO-2026-0001)
        품목코드: 생산할 제품의 품목 코드
        수량: 생산 목표 수량
        납기일: 완료 목표 날짜
        상태: 현재 공정 상태
        담당자: 작업 담당 직원 이름
    """
    지시번호: str
    품목코드: str
    수량: int
    납기일: datetime
    상태: 공정상태 = 공정상태.대기중
    담당자: Optional[str] = None
    비고: str = ""


@dataclass
class 품질검사결과:
    """
    품질 검사 결과를 기록하는 클래스입니다.

    Attributes:
        검사번호: 고유 검사 식별자
        작업지시번호: 연관된 작업 지시 번호
        검사일시: 검사가 수행된 시각
        합격수량: 품질 기준을 통과한 수량
        불합격수량: 품질 기준에 미달한 수량
        불량목록: 발견된 불량 유형 목록
    """
    검사번호: str
    작업지시번호: str
    검사일시: datetime
    합격수량: int
    불합격수량: int
    불량목록: List[불량유형] = field(default_factory=list)

    @property
    def 불량률(self) -> float:
        """불량률을 퍼센트(%) 단위로 반환합니다."""
        전체 = self.합격수량 + self.불합격수량
        if 전체 == 0:
            return 0.0
        return (self.불합격수량 / 전체) * 100.0


