def 품질검사_등록(결과: 품질검사결과) -> bool:
    """
    품질 검사 결과를 시스템에 등록합니다.

    검사 결과를 저장하고 불량률이 기준치(5%)를 초과하면
    관리자에게 알림을 발송합니다.

    Args:
        결과: 등록할 품질 검사 결과 객체

    Returns:
        등록 성공 여부 (True/False)

    Raises:
        ValueError: 검사 수량이 0 이하인 경우
        RuntimeError: 데이터베이스 저장 실패 시
    """
    불량기준치 = 5.0  # 불량률 5% 초과 시 경보

    if 결과.합격수량 + 결과.불합격수량 <= 0:
        raise ValueError("검사 수량은 0보다 커야 합니다.")

    if 결과.불량률 > 불량기준치:
        _관리자_알림_발송(결과)

    # DB 저장 로직 (미구현)
    return True


def 공정상태_변경(지시번호: str, 새상태: 공정상태, 변경사유: str = "") -> bool:
    """
    작업 지시의 공정 상태를 변경합니다.

    상태 변경 이력을 기록하고 변경된 상태를 저장합니다.
    완료 상태로 변경 시 자동으로 실적을 집계합니다.

    Args:
        지시번호: 상태를 변경할 작업 지시 번호
        새상태: 변경할 목표 공정 상태
        변경사유: 상태 변경 이유 (선택적)

    Returns:
        변경 성공 여부
    """
    지시 = 작업지시_조회(지시번호)
    if 지시 is None:
        return False

    이전상태 = 지시.상태
    지시.상태 = 새상태

    # 완료 상태로 전환 시 실적 집계
    if 새상태 == 공정상태.완료:
        _실적_집계(지시번호)

    _상태변경_이력_저장(지시번호, 이전상태, 새상태, 변경사유)
    return True


def 불량_분석_요약(기간_시작: datetime, 기간_종료: datetime) -> dict:
    """
    지정 기간 동안의 불량 발생 현황을 분석하여 요약합니다.

    각 불량 유형별 발생 건수와 비율을 계산하여 반환합니다.
    품질 개선 활동의 우선순위 결정에 활용됩니다.

    Args:
        기간_시작: 분석 시작 날짜/시각
        기간_종료: 분석 종료 날짜/시각

    Returns:
        불량 유형을 키로, 발생 건수와 비율을 값으로 하는 딕셔너리
        예: {"치수불량": {"건수": 12, "비율": 40.0}, ...}
    """
    결과 = {}
    for 유형 in 불량유형:
        결과[유형.name] = {"건수": 0, "비율": 0.0}
    return 결과


