def _관리자_알림_발송(검사결과: 품질검사결과) -> None:
    """불량률 초과 시 담당 관리자에게 알림 메시지를 발송합니다."""
    메시지 = (
        f"[품질 경보] 작업지시 {검사결과.작업지시번호}의 불량률이 "
        f"{검사결과.불량률:.1f}%로 기준치를 초과했습니다."
    )
    # 실제 구현에서는 이메일/SMS 발송
    print(메시지)


